function lastStanding(n: number, k: number): number {
  const players = Array.from({ length: n }, (_, i) => i + 1);
  let at = 0;
  while (players.length > 1) {
    at = (at + k - 1) % players.length;
    players.splice(at, 1); // the next count starts at the same index
  }
  return players[0];
}

